module Lookup
  def cheap?(call) = !call.block && (reader?(call) || keyed?(call)) && !reaching?(call) && !clock?(call)

  def reader?(call) = !call.arguments

  def keyed?(call) = KEYED.include?(call.name) && call.arguments.arguments.all? { KEYS.include?(it.class) }

  def reaching?(call)
    held = call.receiver
    held.is_a?(Prism::CallNode) && held.receiver.is_a?(Prism::Node)
  end

  def clock?(call) = ticks?(call.name, call.receiver&.slice)

  def ticks?(name, receiver) = CLOCKS.include?(name) || (name == :current && CALENDARS.include?(receiver))
end

class Connection
  def in_parallel(manager = nil, &block)
    previous_manager = @parallel_manager
    @parallel_manager = manager || previous_manager || default_parallel_manager do
      warn('Warning: `in_parallel` called but no parallel-capable adapter ' \
           'on Faraday stack', caller[2, 10].join("\n"))
      nil
    end
    return yield unless @parallel_manager && !@parallel_manager.equal?(previous_manager)

    if @parallel_manager.respond_to?(:execute)
      @parallel_manager.execute(&block)
    else
      yield
      @parallel_manager.run
    end
  ensure
    @parallel_manager = previous_manager
  end

  def default_parallel_manager
    @default_parallel_manager ||= begin
      adapter = @builder.adapter.klass if @builder.adapter

      if support_parallel?(adapter)
        adapter.setup_parallel_manager
      elsif block_given?
        yield
      end
    end
  end

  def support_parallel?(adapter)
    adapter.respond_to?(:supports_parallel?) && adapter&.supports_parallel?
  end
end

class Probe
  def doubted? = requested?(receiver, [])

  def requested?(node, seen)
    case node
    when Prism::CallNode then (node.variable_call? && REQUESTS.include?(node.name)) || requested?(node.receiver, seen)
    when Prism::LocalVariableReadNode then traced?(node.name, seen)
    else false
    end
  end

  def traced?(name, seen) = !seen.include?(name) && writes(name).any? { requested?(it.value, seen + [name]) }

  def writes(name) = body.grep(Prism::LocalVariableWriteNode).select { it.name == name }

  def body = @_body ||= Hashira::Smells::Scope.inside(@subject.node)

  def receiver = @call.receiver
end

module FileSet
  def expand(patterns, include: [], exclude: [])
    exclude((Array(patterns) + Array(include)).flat_map { |pattern| resolve(pattern) }.uniq, exclude).sort
  end

  def exclude(files, exclude)
    patterns = Array(exclude)
    excluded = patterns.flat_map { |p| resolve(p) }.to_set
    files.reject { |file| excluded.include?(file) || matches?(file, patterns) }
  end

  def resolve(pattern)
    return Dir.glob(File.join(pattern, "**", "*.rb")) if File.directory?(pattern)
    Dir.glob(pattern).select { |f| File.file?(f) && f.end_with?(".rb") }
  end

  def matches?(file, patterns)
    Array(patterns).any? { |p| File.fnmatch?(p, file, File::FNM_PATHNAME) }
  end
end

class Registry
